<!DOCTYPE html><html lang="en"><head><?php include __DIR__.'/../includes/head.php'; ?></head><body><div class="app-wrapper"><?php include __DIR__.'/../components/sidebar.php'; ?><div class="main-content"><?php include __DIR__.'/../components/navbar.php'; ?><main id="mainContent" class="content-area"><h1 class="h4">Physician Messages</h1><p class="small text-muted">Private participant-scoped physician conversations. Existing nurse conversation history remains in Clinic Messages.</p><?php if($error): ?><p class="alert alert-danger" role="alert"><?=e($error)?></p><?php endif; ?><?php if(permission_profile($u)==='doctor'): ?><form method="post" class="card p-3 mb-3"><?=csrf_field()?><input type="hidden" name="action" value="start"><label for="physician-recipient" class="form-label">Existing patient or nurse account ID</label><input type="number" min="1" name="recipient" id="physician-recipient" required class="form-control"><button class="btn btn-sm btn-primary mt-2 align-self-start">Open authorized conversation</button></form><?php endif; ?><div class="row g-3"><nav class="col-md-4" aria-label="Physician conversations"><?php foreach($threads as $t): ?><a class="card p-3 mb-2" href="<?=APP_URL?>/pages/doctor_messages.php?thread=<?=$t['id']?>">Conversation #<?=$t['id']?> · <?=e($t['updated_at'])?></a><?php endforeach; ?><?php if(!$threads): ?><p class="text-muted">No physician conversations available.</p><?php endif; ?></nav><section class="col-md-8"><?php foreach($messages as $m): ?><article class="card p-3 mb-2"><strong><?=e($m['first_name'].' '.$m['last_name'])?></strong><small class="text-muted"><?=e($m['created_at'])?></small><p class="mb-0"><?=nl2br(e($m['message_body']))?></p></article><?php endforeach; ?><?php if($thread): ?><form method="post" class="card p-3"><?=csrf_field()?><input type="hidden" name="action" value="send"><input type="hidden" name="thread" value="<?=$thread?>"><label class="form-label" for="physician-message">Message</label><textarea name="message" id="physician-message" maxlength="4000" required class="form-control"></textarea><button class="btn btn-sm btn-primary mt-2 align-self-start">Send message</button></form><?php endif; ?></section></div></main></div></div><?php include __DIR__.'/../components/footer.php'; ?></body></html>
